import csv,json,math,re,hashlib
from pathlib import Path
root=Path('.')
rows=[json.loads(x) for x in (root/'input/competition/dataset/test_public/data.jsonl').read_text().splitlines() if x.strip()]
by_id={r['id']:r for r in rows}

def load(path):
    with open(path,newline='') as f:
        rd=csv.DictReader(f)
        data=list(rd)
        header=rd.fieldnames
    vals={}
    bad=[]
    for x in data:
        try: p=int(x['boundary_char_index'])
        except Exception: bad.append((x.get('id'),'non-int')); continue
        vals[x['id']]=p
        if x['id'] not in by_id or not 0<=p<=len(by_id[x['id']]['text']): bad.append((x['id'],'range/id'))
    return header,data,vals,bad
files=['out/v6/submission.csv','candidates/bge_finetune_all_labels_submission.csv','out/v5/submission.csv']
loaded={p:load(p) for p in files}
for p,(h,d,v,b) in loaded.items():
    pred=list(v.values())
    print(p)
    print(' header',h,'rows',len(d),'unique',len(v),'ids_exact',set(v)==set(by_id),'bad',b[:3], 'sha256',hashlib.sha256(Path(p).read_bytes()).hexdigest())
    # Structural output constraints.
    sentence=0; minword=10**9
    for i,prediction in v.items():
        text=by_id[i]['text']
        starts=[0]+[m.end() for m in re.finditer(r'(?<=[.!?])[\"\']?\s+',text)]
        sentence += prediction in starts
        minword=min(minword,len(text[:prediction].split()),len(text[prediction:].split()))
    print(' sentence_starts',sentence,'min_side_words',minword)
for a,b in [(files[0],files[1]),(files[0],files[2]),(files[1],files[2])]:
    va,vb=loaded[a][2],loaded[b][2]
    ds=[abs(va[i]-vb[i]) for i in va if va[i]!=vb[i]]
    print(a,'vs',b,'changed',len(ds),'mean_abs_changed',sum(ds)/len(ds) if ds else 0,'max',max(ds) if ds else 0)
    print([(i,va[i],vb[i]) for i in va if va[i]!=vb[i]][:20])
